describe('Search Term Highlighting in Result Snippets', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should highlight search terms in result snippets when search is performed', () => {
    cy.get('[data-testid="search-input"]').type('cypress automation');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="result-snippet"]').should('be.visible');
    cy.get('[data-testid="result-snippet"]').should('contain', 'cypress automation');

    // Verify highlighting using a specific class or attribute
    cy.get('[data-testid="result-snippet"]').should('have.class', 'highlighted-term');
    cy.get('[data-testid="result-snippet"]').should('contain', '<span class="highlighted-term">cypress</span>');
    cy.get('[data-testid="result-snippet"]').should('contain', '<span class="highlighted-term">automation</span>');

    // Verify the highlighted term has a distinct style
    cy.get('[data-testid="result-snippet"]').should('have.css', 'color', 'rgb(0, 0, 0)');
    cy.get('[data-testid="result-snippet"]').should('have.css', 'background-color', 'rgb(255, 250, 240)');
  });

  it('should handle multiple search terms and edge cases like special characters', () => {
    cy.get('[data-testid="search-input"]').type('cypress automation $123');
    cy.get('[data-testid="search-button"]').click();

    cy.get('[data-testid="result-snippet"]').should('be.visible');
    cy.get('[data-testid="result-snippet"]').should('contain', 'cypress');
    cy.get('[data-testid="result-snippet"]').should('contain', 'automation');
    cy.get('[data-testid="result-snippet"]').should('contain', '$123');

    // Verify all terms are highlighted
    cy.get('[data-testid="result-snippet"]').should('have.class', 'highlighted-term');
    cy.get('[data-testid="result-snippet"]').should('contain', '<span class="highlighted-term">cypress</span>');
    cy.get('[data-testid="result-snippet"]').should('contain', '<span class="highlighted-term">automation</span>');
    cy.get('[data-testid="result-snippet"]').should('contain', '<span class="highlighted-term">$123</span>');

    // Verify highlighting is applied correctly even with special characters
    cy.get('[data-testid="result-snippet"]').should('have.css', 'background-color', 'rgb(255, 250, 240)');
  });
});
